def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    cycle=[3,5,7,9,1]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=0: continue
        if r==0 or r==1:
          out[r][c]=1
        elif r==2:
          out[r][c]=4
        elif c<2:
          out[r][c]=1
        elif c==2:
          out[r][c]=4
        else:
          anchors=[(abs(cc-c),cc,v) for cc,v in enumerate(grid[r]) if v in cycle]
          if anchors:
            _,cc,v=min(anchors)
            out[r][c]=cycle[(cycle.index(v)+(c-cc))%5]
          else:
            out[r][c]=cycle[(c-r)%5]
    return out
