def transform(grid):
    """Reconstruct the repeating 5-color field and preserve the border."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # In these grids the patterned interior is generated rowwise from a
    # five-color cycle. Infer the cycle order and row phase from intact cells.
    palette = [v for v in (3, 5, 7, 9, 1) if any(v in row for row in grid)]
    # Use each row's visible cells to choose the cycle phase. The leading
    # colored frame at columns 0-2 is separate; interior pattern starts at c=3.
    for r in range(3, h):
        known = [(c, grid[r][c]) for c in range(3, w) if grid[r][c] not in (0, 4)]
        if not known:
            continue
        # Find phase giving maximal agreement with the color cycle across row.
        candidates = []
        for phase in range(len(palette)):
            score = sum(palette[(phase + c - 3) % len(palette)] == v for c, v in known)
            candidates.append((score, phase))
        phase = max(candidates)[1]
        for c in range(3, w):
            if grid[r][c] == 0:
                out[r][c] = palette[(phase + c - 3) % len(palette)]
    # Restore zeroed pieces of the decorative left/top border from their shape.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or c >= 3:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            else:
                out[r][c] = 4
    return out
